import fs from 'node:fs';import{createHash}from'node:crypto';import{retainedAssetKey}from'../../services/vii-edge-delivery/src/retained-assets.ts';
const dir='.qa-output/phase14-active-assets',m=JSON.parse(fs.readFileSync(dir+'/manifest.json','utf8')),original=JSON.parse(fs.readFileSync(dir+'/observed-client-manifest.json','utf8')),op=JSON.parse(fs.readFileSync('.qa-output/phase14-seed-operation.json','utf8'));const expected=new Set();for(const v of Object.values(original))for(const p of [v.file,...v.css||[],...v.assets||[]])expected.add('/'+p);
if(JSON.stringify([...expected].sort())!==JSON.stringify(m.files.map(x=>x.path).sort()))throw Error('Declared output inventory differs');if(Date.now()-Date.parse(op.finishedAt)>3600000||op.status!=='all_objects_private_readback_verified'||op.verified!==expected.size||op.manifestSha256!==m.manifestSha256)throw Error('Actual storage readback incomplete');
for(const row of m.files){if(row.key!==await retainedAssetKey(row.path))throw Error('Derived request key differs');const bytes=fs.readFileSync(dir+'/'+row.key.split('/')[1]+'.bin'),length=bytes.readUInt32BE(0),meta=JSON.parse(bytes.subarray(4,4+length));if(meta.source!==m.source||meta.buildId!==m.buildId||meta.path!==row.path||meta.sha256!==row.sha256||meta.bytes!==row.bytes)throw Error('Stored envelope provenance differs');const receipt=op.entries.find(x=>x.key===row.key);if(!receipt||!['stored_readback_verified','already_verified'].includes(receipt.status)||receipt.sha256!==createHash('sha256').update(bytes).digest('hex'))throw Error('Exact remote readback does not bind the local envelope');}
const result={status:'passed',scope:'independent full declared-inventory, derived lookup key and envelope provenance verification tied to actual per-object cloud binary readbacks',fileCount:expected.size,totalBytes:m.totalBytes,manifestSha256:m.manifestSha256,source:m.source,buildId:m.buildId,bucket:op.bucket,observedAt:new Date().toISOString(),publicEdgeDeployed:false};fs.writeFileSync('.qa-output/phase14-independent-completeness.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));

